/** `native-engine-unavailable`: A native engine that is missing, cannot load, or predates this compiler. */
export const NATIVE_ENGINE_UNAVAILABLE: SzBrowserDiagnostic<{ readonly form: 'no-platform-package' | 'not-installed' | 'missing-export' | 'stale-binding' | 'wasm-fallback'; readonly platform?: string; readonly packageName?: string; readonly exportName?: string }> = {"id":"native-engine-unavailable","args":{"form":{},"platform":{},"packageName":{},"exportName":{}},"text":{"no-platform-package":"No prebuilt native engine covers `{platform}`, so the `rust` parser cannot run.","not-installed":"`{packageName}` is not installed, so the `rust` parser cannot run.","missing-export":"`{packageName}` does not export `{exportName}()`, which the installed `@csszyx/core` calls, so the `rust` parser cannot run.","stale-binding":"`{packageName}` is older than the installed `@csszyx/core` and returns results it cannot read, so the `rust` parser cannot run.","wasm-fallback":"The native engine is not available here, so the default `rust` parser runs on the wasm engine."},"help":{"no-platform-package":"set the parser to `wasm` (`build.parser: 'wasm'` in the plugin options, `parserMode: 'wasm'` in `csszyxTurbopack`, or `--parser-mode wasm` on `csszyx next`); the wasm engine ships inside `@csszyx/core`.","not-installed":"reinstall without skipping optional dependencies, which installs `{packageName}` with `@csszyx/core`, or set the parser to `wasm` (`build.parser: 'wasm'` in the plugin options, `parserMode: 'wasm'` in `csszyxTurbopack`, or `--parser-mode wasm` on `csszyx next`).","missing-export":"update `@csszyx/core` and `{packageName}` together, to the same version, or set the parser to `wasm` (`build.parser: 'wasm'` in the plugin options, `parserMode: 'wasm'` in `csszyxTurbopack`, or `--parser-mode wasm` on `csszyx next`).","stale-binding":"update `@csszyx/core` and `{packageName}` together, to the same version, or set the parser to `wasm` (`build.parser: 'wasm'` in the plugin options, `parserMode: 'wasm'` in `csszyxTurbopack`, or `--parser-mode wasm` on `csszyx next`).","wasm-fallback":"reinstall without skipping optional dependencies to get the native engine, or set `build.parser: 'wasm'` to hide this line."},"note":"the wasm engine produces the same output; only parsing is slower."};

