export const MANGLE_MAP_TOO_LARGE: SzBrowserDiagnostic<{ readonly size: number; readonly maxBytes: number }> = {"id":"mangle-map-too-large","args":{"size":{},"maxBytes":{}},"text":"The CSS variable mangle map is {size} bytes, over its safety cap of {maxBytes} bytes, so the build stops.","help":"turn `production.mangleVars` off or split the bundle; to accept this size, raise the `CSSZYX_VAR_MANGLE_MAP_MAX_BYTES` environment variable above {size}."};

/** `mangle-census-late`: Classes that appeared after the mangle map was frozen. */
export const MANGLE_CENSUS_LATE: SzBrowserDiagnostic<{ readonly form: 'classes' | 'census-changed'; readonly classes?: readonly string[] }> = {"id":"mangle-census-late","args":{"form":{},"classes":{"joiner":"`, `"}},"text":{"classes":"`{classes}` appeared after the mangle map was frozen, so the CSS emitted before then used another map, and the build stops.","census-changed":"The class census changed after the mangle map was frozen, so the CSS emitted before then used another map, and the build stops."},"help":{"classes":"move the file that uses them under the project root or a `compileSources` directory, which the prescan walks; otherwise, set `production.mangle: false` for this build.","census-changed":"move every file that uses csszyx under the project root or a `compileSources` directory, which the prescan walks; otherwise, set `production.mangle: false` for this build."}};

/** `mangle-hybrid-hazard`: A production mangle that collides with, or breaks, CSS csszyx did not write. */
export const MANGLE_HYBRID_HAZARD: SzBrowserDiagnostic<{ readonly form: 'collision' | 'orphan' | 'selector-renamed' | 'selector-matched'; readonly count: number; readonly names?: readonly string[]; readonly selectors?: readonly string[]; readonly entries?: readonly string[] }> = {"id":"mangle-hybrid-hazard","args":{"form":{},"count":{},"names":{"joiner":"`, `"},"selectors":{"joiner":"`; `"},"entries":{"joiner":", "}},"text":{"collision":"Mangling renamed classes to {count} token(s) that CSS outside csszyx also uses as class names, such as `{names}`, so the renamed elements pick up that CSS and the elements it was written for pick up the csszyx rules.","orphan":"Mangling renamed {count} class(es) that no stylesheet in this build has a rule for, such as `{names}`, so a stylesheet outside this build that styles them by name, such as one a separate Tailwind run writes, no longer matches them.","selector-renamed":"Mangling broke {count} attribute selector(s) that match class names by text, such as `{selectors}`, so those rules stop matching and the elements lose those styles.","selector-matched":"Mangling made {count} attribute selector(s) match the tokens it renamed classes to, such as `{selectors}`, so their rules style elements they were not written for."},"help":{"collision":"rename those classes in your own CSS to something specific, such as `.x` to `.resize-handle-x`, and list the ones in a stylesheet you cannot edit in `production.mangleExclude`; until then, pass `production: { mangle: false }` to the csszyx plugin.","orphan":"build that stylesheet through this bundler, so csszyx renames its rules too; until then, pass `production: { mangle: false }` to the csszyx plugin.","selector-renamed":"keep those classes readable with `production.manglePreserve: [{entries}]`, or select on a data attribute, which mangling never changes.","selector-matched":"reserve those tokens with `production.mangleExclude: [{entries}]`, or select on a data attribute, which mangling never changes."},"note":{"collision":"`csszyx scan-collisions` lists every class name in your stylesheets that a token could take, as a `mangleExclude` list you can paste.","selector-renamed":"`production.mangleExclude` does not help here: it reserves token names and still lets the class be renamed.","selector-matched":"a prefix or substring selector can match tokens a later build allocates too, so the data attribute is the lasting fix.","orphan":"a class that no stylesheet styles had no CSS before the rename either, so it changes nothing."}};

/** `merge-hook-late`: A rule selecting on a class the build had already merged away. */
export const MERGE_HOOK_LATE: SzBrowserDiagnostic<{ readonly className: string }> = {"id":"merge-hook-late","args":{"className":{}},"text":"`{className}` was removed from this file before csszyx read a rule that selects on it, so the page would lose that class, and the build stops.","help":"set `build.mergeCoveredClasses: false` to keep every class, or restart the watch session.","note":"csszyx reads such rules during the prescan, before it merges; this one came later, from a module the prescan did not reach or from an edit during a watch session."};

/** `merge-origin-unreadable`: A Tailwind stylesheet csszyx cannot recompile without its own classes, so the build merges no class. */
export const MERGE_ORIGIN_UNREADABLE: SzBrowserDiagnostic<{ readonly reason: string }> = {"id":"merge-origin-unreadable","args":{"reason":{}},"text":"This Tailwind stylesheet did not compile once csszyx took out its `@utility` blocks and plugin classes, so csszyx cannot tell Tailwind's classes from the project's and merges no class in this build.","help":"report this csszyx bug at https://github.com/nguyennhutien/csszyx/issues with this message and the plugin or `@utility` block the stylesheet uses.","note":"every class is kept, so `{ pb: 2, p: 4 }` emits `pb-2 p-4`, a `className` class stays beside the `sz` classes, and `szcn` removes only exact repeats; the compile reported: {reason}."};

/** `tailwind-stylesheet-missing`: A configured Tailwind stylesheet that does not exist. */
export const TAILWIND_STYLESHEET_MISSING: SzBrowserDiagnostic<{ readonly setting: string; readonly missing: readonly string[]; readonly root: string }> = {"id":"tailwind-stylesheet-missing","args":{"setting":{},"missing":{"joiner":"`, `"},"root":{}},"text":"The stylesheet(s) `{missing}` named by {setting} do not exist under `{root}`, so the build stops.","help":"list the Tailwind stylesheet this build loads, relative to the project root."};

/** `tailwind-stylesheet-absent`: A build that emitted classes for `sz` props and processed no Tailwind stylesheet. */
export const TAILWIND_STYLESHEET_ABSENT: SzBrowserDiagnostic<{ readonly count: number }> = {"id":"tailwind-stylesheet-absent","args":{"count":{}},"text":"This build emitted {count} class(es) for `sz` props and processed no Tailwind stylesheet, so none of those classes produces CSS.","help":"add `@import \"tailwindcss\";` to a stylesheet the app loads; csszyx adds the `@source` for its safelist there itself."};

/** `tailwind-stylesheet-broken`: A stylesheet reaching Tailwind that does not compile, so the prefix is unknown. */
export const TAILWIND_STYLESHEET_BROKEN: SzBrowserDiagnostic<{ readonly stylesheets: readonly string[]; readonly setting: string }> = {"id":"tailwind-stylesheet-broken","args":{"stylesheets":{"joiner":"\n    "},"setting":{}},"text":"A Tailwind stylesheet did not compile, so csszyx cannot read the Tailwind prefix and transforms no module.","help":"fix the stylesheet; if this build does not load it, list the stylesheets it does load with {setting}.","note":"each failure, as Tailwind reported it:\n    {stylesheets}"};

