/** `legacy-source-directive`: An @source line naming the old safelist file, which csszyx no longer writes. */
export const LEGACY_SOURCE_DIRECTIVE: SzBrowserDiagnostic<{ readonly target: string }> = {"id":"legacy-source-directive","args":{"target":{}},"text":"`@source \"{target}\"` names the old safelist, which csszyx no longer writes, so the build stops.","help":"remove this line; on Next.js, also list `'@csszyx/unplugin/postcss'` before `'@tailwindcss/postcss'` in `postcss.config`.","note":"csszyx adds the `@source` for `.csszyx/csszyx-classes.txt` itself: the Vite, Rollup and webpack plugins inject it, and on Next.js `@csszyx/unplugin/postcss` does."};

/** `postcss-plugin-order`: The csszyx PostCSS plugin listed after Tailwind, which then never reads the safelist. */
export const POSTCSS_PLUGIN_ORDER: SzBrowserDiagnostic<Record<never, never>> = {"id":"postcss-plugin-order","args":{},"text":"`@csszyx/unplugin/postcss` is listed after `@tailwindcss/postcss`, so Tailwind compiles the stylesheet before csszyx adds the safelist, and the build stops.","help":"list `'@csszyx/unplugin/postcss'` before `'@tailwindcss/postcss'` in `postcss.config`."};

/** `postcss-plugin-missing`: A Next.js PostCSS config that does not list the csszyx plugin, so Tailwind never reads the safelist. */
export const POSTCSS_PLUGIN_MISSING: SzBrowserDiagnostic<Record<never, never>> = {"id":"postcss-plugin-missing","args":{},"text":"The PostCSS config Next.js reads does not list `@csszyx/unplugin/postcss`, so Tailwind never reads the safelist and no `sz` class produces CSS.","help":"add `@csszyx/unplugin/postcss` to its plugins, before `@tailwindcss/postcss`."};

/** `ignore-pattern-negated`: A negated pattern in an ignore list, which can only add paths. */
export const IGNORE_PATTERN_NEGATED: SzBrowserDiagnostic<{ readonly pattern: string }> = {"id":"ignore-pattern-negated","args":{"pattern":{}},"text":"The ignore pattern `{pattern}` is negated, and an ignore list cannot take one, so csszyx stops.","help":"narrow the pattern that covers too much, so that nothing has to be taken back out.","note":"each pattern only adds paths to leave out."};

/** `compile-sources-unresolved`: A `compileSources` path that does not resolve to a directory. */
export const COMPILE_SOURCES_UNRESOLVED: SzBrowserDiagnostic<{ readonly paths: readonly string[]; readonly root: string }> = {"id":"compile-sources-unresolved","args":{"paths":{"joiner":"`, `"},"root":{}},"text":"The `compileSources` path(s) `{paths}` do not resolve to a directory from `{root}`, so the build compiles nothing from them and adds none of their classes to the safelist.","help":"point each path at a directory, relative to the project root or absolute, such as `compileSources: ['../../packages/vui']`."};

/** `compile-sources-skipped`: Files under `packages/` that use csszyx and that the build skips, since `compileSources` does not list them. */
export const COMPILE_SOURCES_SKIPPED: SzBrowserDiagnostic<{ readonly form: 'sz' | 'szv-exports'; readonly count: number; readonly files: readonly string[]; readonly szvCount?: number }> = {"id":"compile-sources-skipped","args":{"form":{},"count":{},"files":{"joiner":"\n    "},"szvCount":{}},"text":"The build skipped {count} file(s) under `packages/` that use csszyx, so it compiles none of their `sz` props and none of their classes reach the safelist.","help":"add the package directory to `compileSources`, such as `compileSources: ['packages/ui']`, or move the files out of `packages/`.","note":{"sz":"the skipped files:\n    {files}","szv-exports":"of these, {szvCount} may export `szv` factories, so another module that calls one runs it at runtime instead of getting its classes compiled in; the skipped files:\n    {files}"}};

