/** `rsc-boundary-violation`: A client-only csszyx export imported into a Server Component. */
export const RSC_BOUNDARY_VIOLATION: SzBrowserDiagnostic<{ readonly symbol: string; readonly chain: readonly string[] }> = {"id":"rsc-boundary-violation","args":{"symbol":{},"chain":{"joiner":"` -> `"}},"text":"This Server Component reaches `{symbol}` through its imports, and `{symbol}` runs only on the client, so the build stops.","help":"add `'use client'` to the module of `{chain}` that uses `{symbol}`, or keep that module out of server code; csszyx inserts `{symbol}` where an `sz` prop's value is known only at runtime."};

/** `next-prefix-unread`: A Next lane that runs before the Tailwind prefix was read. */
export const NEXT_PREFIX_UNREAD: SzBrowserDiagnostic<{ readonly lane: 'prebuild' | 'turbopack-loader'; readonly root: string; readonly reason: string }> = {"id":"next-prefix-unread","args":{"lane":{},"root":{},"reason":{}},"variesBy":"lane","text":{"prebuild":"The Next prebuild has no Tailwind prefix for `{root}` ({reason}), so it stops.","turbopack-loader":"The Turbopack loader has no Tailwind prefix for `{root}` ({reason}), so it stops."},"help":{"prebuild":"run it through `csszyx next prebuild`, which reads the stylesheets first; from a script, call `prepareNextStylesheetFacts` before `runNextPrebuild`.","turbopack-loader":"run `csszyx next prebuild` before `next build`, and `csszyx next watch` beside `next dev`; both read the stylesheets first."},"note":{"prebuild":"no file was transformed, and the safelist was not written.","turbopack-loader":"this module was not transformed."}};

/** `next-safelist-locked`: A Next safelist state another live process holds the lock on. */
